// Form companion: client/components/user/form/tac.js
export default class {
  form = { name: '' }
  @publish('users.changed')
  changed = 0

  async save() {
    const response = await this.tac.fetch('/users', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify(this.form),
    })
    if (!response.ok) throw new Error('Save failed')
    this.changed += 1
  }
}

// List companion: client/components/user/list/tac.js
export default class {
  users = []
  @subscribe('users.changed')
  @onMount
  async refresh() {
    const response = await this.tac.fetch('/users', { cache: 'no-store' })
    this.users = await response.json()
  }
}

